draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw book
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-50, H/2-75, 100, 150);
  ctx.strokeRect(W/2-50, H/2-75, 100, 150);

  // Draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2, H/2+120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+90);
  ctx.lineTo(W/2-30, H/2+60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+90);
  ctx.lineTo(W/2+30, H/2+60);
  ctx.stroke();

  // Draw wisdom bubbles
  ctx.fillStyle = 'lightblue';
  ctx.beginPath();
  ctx.arc(W/2-60+30*Math.sin(t), H/2-30, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2+60+30*Math.cos(t), H/2-80, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw lesson text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1612', W/2, H/2-120+20*Math.sin(t));

  ctx.restore();
}
